begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','40100000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('40100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','reimbursement-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Receipt confirmation fixture','UTC','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Villa' from ctx returning id) select * from c;
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('40100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Reimbursement member '||i,case when i=4 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,4) i;
create temp table members as select right(user_id::text,1)::int n,id from public.project_members where project_id=(select id from ctx);
grant select on members to authenticated;
select pg_temp.login(1);
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Villa","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from activity),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
create temp table payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,activity.id,members.id,'full','outgoing','paid',90000,current_date from ctx,activity,members where n=1 returning id) select * from p;
insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select ctx.id,activity.id,'Vendor schedule',90000,current_date+30 from ctx,activity;
create temp table before_schedules as select jsonb_agg(to_jsonb(s) order by payment_schedule_id) doc from public.v_activity_payment_schedule_financials s where project_id=(select id from ctx);
create temp table before_financial as select to_jsonb(f) doc from public.v_project_financials f where project_id=(select id from ctx);
create temp table before_balances as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.v_activity_member_settlements s where commitment_id=(select id from activity);
create temp table before_member_balances as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.v_member_balances s where project_id=(select id from ctx);
create temp table before_shares as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.cost_shares s where commitment_id=(select id from activity);
create temp table request_a as select public.create_reimbursement((select id from payment),(select id from members where n=2),30000) id;
create temp table request_b as select public.create_reimbursement((select id from payment),(select id from members where n=3),30000) id;
create function pg_temp.financial_snapshot() returns jsonb language sql as $$
 select jsonb_build_object('project',(select jsonb_agg(to_jsonb(t)) from public.v_project_financials t where project_id=(select id from ctx)),
 'activity',(select jsonb_agg(to_jsonb(t) order by member_id) from public.v_activity_member_settlements t where project_id=(select id from ctx)),
 'members',(select jsonb_agg(to_jsonb(t) order by member_id) from public.v_member_balances t where project_id=(select id from ctx)),
 'schedules',(select jsonb_agg(to_jsonb(t) order by payment_schedule_id) from public.v_activity_payment_schedule_financials t where project_id=(select id from ctx)),
 'payments',(select jsonb_agg(to_jsonb(t) order by id) from public.payments t where project_id=(select id from ctx)),
 'shares',(select jsonb_agg(to_jsonb(t) order by member_id) from public.cost_shares t where project_id=(select id from ctx)),
 'requests',(select jsonb_agg(to_jsonb(t) order by id) from public.reimbursement_requests t where project_id=(select id from ctx)));
$$;
select pg_temp.login(2);
create temp table ack as select public.acknowledge_reimbursement_payment((select id from request_a)) id;
select throws_ok($$select public.confirm_reimbursement_receipt((select id from ack))$$,'42501',null,'Debtor cannot self-confirm');
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select id from ack))$$,'42501',null,'Unrelated member denied');
select pg_temp.login(5);
select throws_ok($$select public.confirm_reimbursement_receipt((select id from ack))$$,'42501',null,'Outsider denied');
select pg_temp.login(1);
create temp table baseline as select pg_temp.financial_snapshot() doc;
select ok((select can_confirm from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),'Actual creditor can confirm');
create temp table before_completion as select app.commitment_financially_settled((select id from activity)) value;
create temp table confirmation as select public.confirm_reimbursement_receipt((select id from ack)) id;
select is(public.confirm_reimbursement_receipt((select id from ack)),(select id from confirmation),'Exact retry returns same confirmation');
select is((select count(*)::int from public.payments where project_id=(select id from ctx) and settlement_group_id is not null),2,'Exactly two settlement rows');
select is((select status from public.v_reimbursements where id=(select id from request_a)),'settled','Request settled');
select is((select remaining_minor from public.v_activity_member_settlements where commitment_id=(select id from activity) and member_id=(select id from members where n=2)),0::bigint,'Debtor remaining cleared');
select is((select remaining_minor from public.v_activity_member_settlements where commitment_id=(select id from activity) and member_id=(select id from members where n=1)),-30000::bigint,'Creditor credit reduced by exact amount');
select is((pg_temp.financial_snapshot()->'project'),(select doc->'project' from baseline),'Project spend unchanged');
select is(app.commitment_financially_settled((select id from activity)),(select value from before_completion),'Existing completion predicate still derives financial eligibility without auto-completing');
select isnt((select status::text from public.commitments where id=(select id from activity)),'completed','Confirmation does not auto-complete Activity');
select is((pg_temp.financial_snapshot()->'shares'),(select doc->'shares' from baseline),'Shares unchanged');
select is((pg_temp.financial_snapshot()->'schedules'),(select doc->'schedules' from baseline),'Schedules unchanged');
select throws_ok($$select public.cancel_reimbursement((select id from request_a))$$,'42501',null,'Settled request cannot be cancelled');
select pg_temp.login(2);
select throws_ok($$select public.withdraw_reimbursement_payment_acknowledgement((select id from ack))$$,'42501',null,'Confirmed claim cannot be undone');
select is((select count(*)::int from public.v_my_receipt_confirmation_notifications where project_id=(select id from ctx)),1,'Debtor receipt notification');
set local role postgres;
set constraints all immediate;
set constraints all deferred;
select is((select count(*)::int from app.domain_events where resource_id=(select id from confirmation)),1,'One confirmation event');
select is((select payload from app.domain_events where resource_id=(select id from confirmation)),jsonb_build_object('activity_id',(select id from activity),'reimbursement_request_id',(select id from request_a),'acknowledgement_id',(select id from ack)),'Exact minimal event payload');
select is((select actor_user_id from app.domain_events where resource_id=(select id from confirmation)),'40100000-0000-4000-8000-000000000001'::uuid,'Confirmation event actor is creditor');
select is((select recipient_user_id from public.notifications where receipt_confirmation_id=(select id from confirmation)),'40100000-0000-4000-8000-000000000002'::uuid,'Only debtor notified');
select is((select count(*)::int from public.notifications where receipt_confirmation_id=(select id from confirmation)),1,'One debtor notification');
select is((select count(*)::int from app.domain_event_processing where event_id in(select id from app.domain_events where resource_id=(select id from confirmation))),1,'One processing receipt');
select is((select count(*)::int from app.automation_action_runs where event_id in(select id from app.domain_events where resource_id=(select id from confirmation))),1,'One action receipt');
select pg_temp.login(1);
select is((select count(*)::int from public.payments where settlement_group_id=(select settlement_group_id from public.reimbursement_receipt_confirmations where id=(select id from confirmation)) and ((direction='outgoing' and type='full' and paid_by_member_id=(select id from members where n=2)) or(direction='incoming' and type='refund' and paid_by_member_id=(select id from members where n=1)))),2,'Correct debtor to creditor pair structure');
select is((select confirmed_at between transaction_timestamp() and clock_timestamp() from public.reimbursement_receipt_confirmations where id=(select id from confirmation)),true,'Server confirmation timestamp');
select is((select created_by_user_id from public.reimbursement_receipt_confirmations where id=(select id from confirmation)),auth.uid(),'Creditor actor derived');
select is((select count(*)::int from public.get_project_health((select id from ctx)) where code='reimbursement_confirmation' and subject_id=(select id from request_a)),0,'Confirmed creditor attention clears');
select is((select count(*)::int from public.v_my_payment_acknowledgement_notifications where reimbursement_id=(select id from request_a)),0,'Old creditor claim notice hidden after confirmation');
select public.cancel_item_settlement((select settlement_group_id from public.reimbursement_receipt_confirmations where id=(select id from confirmation)));
select is((select confirmation_state from public.v_reimbursement_payment_status where reimbursement_request_id=(select id from request_a)),'reversed','Existing correction derives reversed state');
select is((select remaining_minor from public.v_activity_member_settlements where commitment_id=(select id from activity) and member_id=(select id from members where n=2)),30000::bigint,'Correction restores balance');
select is((select count(*)::int from public.reimbursement_receipt_confirmations where id=(select id from confirmation)),1,'Correction retains confirmation history');
-- Additional independent Activities exercise authority and current-basis boundaries.
select pg_temp.login(1);
create function pg_temp.make_case() returns jsonb language plpgsql as $$
declare a uuid; p uuid; r uuid;
begin
 a:=(public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Confirmation boundary","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
 perform public.set_activity_cost_split(a,jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n in(2,3))));
 insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) values((select id from ctx),a,(select id from members where n=3),'full','outgoing','paid',90000,current_date) returning id into p;
 r:=public.create_reimbursement(p,(select id from members where n=2),45000);
 return jsonb_build_object('activity',a,'payment',p,'request',r);
end $$;
create temp table scenario(doc jsonb,ack uuid);
insert into scenario(doc) select pg_temp.make_case();
select pg_temp.login(2);
update scenario set ack=public.acknowledge_reimbursement_payment((doc->>'request')::uuid);
select pg_temp.login(1);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Observer Organizer cannot impersonate Member creditor');
select pg_temp.login(3);
select is(app.commitment_financially_settled((select (doc->>'activity')::uuid from scenario)),false,'Outstanding member balance blocks completion');
select lives_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'Member creditor uses narrow confirmation authority');
select is(app.commitment_financially_settled((select (doc->>'activity')::uuid from scenario)),true,'Full confirmation naturally enables existing completion predicate');
select isnt((select status::text from public.commitments where id=(select (doc->>'activity')::uuid from scenario)),'completed','Financial eligibility does not auto-complete Activity');
select throws_ok($$select public.record_item_settlement((select (doc->>'activity')::uuid from scenario),(select id from members where n=2),(select id from members where n=3),1,current_date)$$,'42501',null,'Member still cannot call general settlement');
select throws_ok($$select app.record_item_settlement((select (doc->>'activity')::uuid from scenario),(select id from members where n=2),(select id from members where n=3),1,current_date,gen_random_uuid())$$,'42501',null,'Private core is not callable by client');
select throws_ok($$update public.reimbursement_receipt_confirmations set confirmed_at=now()$$,'42501',null,'Direct confirmation edits denied');
select throws_ok($$delete from public.reimbursement_receipt_confirmations$$,'42501',null,'Direct confirmation delete denied');
select pg_temp.login(1);
select public.set_activity_cost_split((select (doc->>'activity')::uuid from scenario),jsonb_build_object('mode','custom','cost',90000,'members',(select jsonb_agg(id) from members where n in(2,3)),'amounts',(select jsonb_object_agg(id::text,case when n=2 then 30000 else 60000 end) from members where n in(2,3))));
select is((select confirmation_state from public.v_reimbursement_payment_status where reimbursement_request_id=(select (doc->>'request')::uuid from scenario)),'settled','Later share edit preserves confirmed history');
select is((select remaining_minor from public.v_activity_member_settlements where commitment_id=(select (doc->>'activity')::uuid from scenario) and member_id=(select id from members where n=2)),-15000::bigint,'Later share edit flows through existing balance engine');

select pg_temp.login(1);
truncate scenario;
insert into scenario(doc) select pg_temp.make_case();
select pg_temp.login(2);
update scenario set ack=public.acknowledge_reimbursement_payment((doc->>'request')::uuid);
select pg_temp.login(1);
update public.project_members set role='viewer' where id=(select id from members where n=3);
select pg_temp.login(3);
select lives_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'Viewer actual creditor can confirm only their precise pair');
select throws_ok($$insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,(doc->>'activity')::uuid,members.id,'full','outgoing','paid',1,current_date from ctx,scenario,members where n=3$$,'42501',null,'Viewer general payment permission unchanged');
select pg_temp.login(1);
update public.project_members set role='member' where id=(select id from members where n=3);
truncate scenario;
insert into scenario(doc) select pg_temp.make_case();
select pg_temp.login(2);
update scenario set ack=public.acknowledge_reimbursement_payment((doc->>'request')::uuid);
select public.withdraw_reimbursement_payment_acknowledgement((select ack from scenario));
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Withdrawn acknowledgement denied');
select pg_temp.login(2);
select public.acknowledge_reimbursement_payment((select (doc->>'request')::uuid from scenario));
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Old acknowledgement denied after re-acknowledgement');
select pg_temp.login(1);
select public.cancel_reimbursement((select (doc->>'request')::uuid from scenario));
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select id from public.reimbursement_payment_acknowledgements where reimbursement_request_id=(select (doc->>'request')::uuid from scenario) and withdrawn_at is null))$$,'42501',null,'Cancelled request denied');
select pg_temp.login(1);
truncate scenario;
insert into scenario(doc) select pg_temp.make_case();
select pg_temp.login(2);
update scenario set ack=public.acknowledge_reimbursement_payment((doc->>'request')::uuid);
select pg_temp.login(1);
update public.projects set status='archived' where id=(select id from ctx);
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Archived confirmation denied');
select pg_temp.login(1);
update public.projects set status='active' where id=(select id from ctx);
update public.project_members set status='removed' where id=(select id from members where n=3);
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Removed creditor denied');
select pg_temp.login(1);
update public.project_members set status='active' where id=(select id from members where n=3);
update public.project_members set status='removed' where id=(select id from members where n=2);
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Removed debtor denies creditor confirmation');
select pg_temp.login(1);
update public.project_members set status='active' where id=(select id from members where n=2);
create temp table join_token as select public.regenerate_project_join_link((select id from ctx)) token;
select pg_temp.login(5);
select public.request_project_access((select token from join_token));
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Pending requester denied');
create temp table outside_project as select public.create_project('Confirmation outsider','UTC','GBP','2026-01-01') id;
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Cross-project Organizer denied');
select is((select count(*)::int from public.reimbursement_receipt_confirmations where project_id=(select id from ctx)),0,'Cross-project confirmation history hidden');
select public.soft_delete_project((select id from outside_project));
select pg_temp.login(1);
-- All changes below are ordinary existing domain mutations, never confirmation side effects.
insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,(doc->>'activity')::uuid,members.id,'refund','incoming','paid',1000,current_date from ctx,scenario,members where n=3;
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Refund before confirmation denies stale basis');
select is((select count(*)::int from public.payments where commitment_id=(select (doc->>'activity')::uuid from scenario) and settlement_group_id is not null),0,'Stale refund creates no settlement');
select pg_temp.login(1);
truncate scenario;
insert into scenario(doc) select pg_temp.make_case();
select pg_temp.login(2);
update scenario set ack=public.acknowledge_reimbursement_payment((doc->>'request')::uuid);
select pg_temp.login(1);
select public.set_activity_cost_split((select (doc->>'activity')::uuid from scenario),jsonb_build_object('mode','custom','cost',90000,'members',(select jsonb_agg(id) from members where n in(2,3)),'amounts',(select jsonb_object_agg(id::text,case when n=2 then 30000 else 60000 end) from members where n in(2,3))));
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Share edit before confirmation denied');
select pg_temp.login(1);
truncate scenario;
insert into scenario(doc) select pg_temp.make_case();
select pg_temp.login(2);
update scenario set ack=public.acknowledge_reimbursement_payment((doc->>'request')::uuid);
select pg_temp.login(1);
select public.record_item_settlement((select (doc->>'activity')::uuid from scenario),(select id from members where n=2),(select id from members where n=3),45000,current_date);
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Independent full settlement denies double settlement');
select is((select count(*)::int from public.payments where commitment_id=(select (doc->>'activity')::uuid from scenario) and settlement_group_id is not null),2,'No second pair after independent settlement');
select pg_temp.login(1);
truncate scenario;
insert into scenario(doc) select pg_temp.make_case();
select pg_temp.login(2);
update scenario set ack=public.acknowledge_reimbursement_payment((doc->>'request')::uuid);
set local role postgres;
create function pg_temp.reject_receipt_notification() returns trigger language plpgsql as $$ begin if new.kind='reimbursement_receipt_confirmed' then raise exception 'Test atomic rollback'; end if; return new; end $$;
create trigger test_receipt_failure before insert on public.notifications for each row execute function pg_temp.reject_receipt_notification();
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'P0001','Test atomic rollback','Notification failure rolls back confirmation transaction');
select is((select count(*)::int from public.reimbursement_receipt_confirmations where acknowledgement_id=(select ack from scenario)),0,'Atomic failure leaves no confirmation');
select is((select count(*)::int from public.payments where commitment_id=(select (doc->>'activity')::uuid from scenario) and settlement_group_id is not null),0,'Atomic failure leaves no orphan settlement');
select is((select status from public.v_reimbursements where id=(select (doc->>'request')::uuid from scenario)),'open','Atomic failure leaves request open');
set local role postgres;
drop trigger test_receipt_failure on public.notifications;
select pg_temp.login(1);
select public.soft_delete_commitment((select (doc->>'activity')::uuid from scenario));
select pg_temp.login(3);
select throws_ok($$select public.confirm_reimbursement_receipt((select ack from scenario))$$,'42501',null,'Deleted Activity denied');
select pg_temp.login(1);

select public.soft_delete_project((select id from ctx));
select is((select count(*)::int from public.reimbursement_receipt_confirmations where project_id=(select id from ctx)),0,'Deleted project hides confirmation');
select throws_ok($$select public.confirm_reimbursement_receipt((select id from ack))$$,'42501',null,'Deleted project denied');
set local role anon;
select throws_ok($$select public.confirm_reimbursement_receipt(null)$$,'42501',null,'Anonymous confirmation denied');
select throws_ok($$select * from public.reimbursement_receipt_confirmations$$,'42501',null,'Anonymous read denied');
set local role postgres;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.reimbursement_receipt_confirmations'::regclass),'Confirmation RLS enabled and forced');
select throws_ok($$update public.reimbursement_receipt_confirmations set settlement_group_id=gen_random_uuid() where id=(select id from confirmation)$$,'P0001',null,'Historical confirmation linkage immutable even for accidental privileged writes');
select * from finish();
rollback;
